#include "chunk_gated_delta_net.cuh"
#include <cmath>

// Tensor-core backend for the chunked-GDN GEMMs, Default nvcuda::wmma (fastest on NVIDIA).
// And ggml_cuda_mma API is used on HIP/MUSA.
#if defined(GGML_CUDA_GDN_FORCE_MMA) || defined(GGML_USE_HIP) || defined(GGML_USE_MUSA)
#define GDN_TC_MMA 1
#else
#define GDN_TC_MMA 0
#endif

// GDN_ACC_DL: the 16x16 f32 accumulator fragment layout is J_MAJOR on CDNA and RDNA
// (mma.cuh: "Matrix C for CDNA and RDNA4, int and float matrix C for RDNA3") and I_MAJOR on
// NVIDIA. get_i/get_j report where each lane's accumulator element lands, so declaring the
// wrong layout transposes the mapping and scatters the whole tile to the wrong shared-memory
// slots. Matches PR #24561 (validated 48/48 on MI250X/gfx90a) and the mmf.cuh tile_C choice.
#if defined(AMD_MFMA_AVAILABLE) || defined(AMD_WMMA_AVAILABLE)
#  define CGDR_C_DL ggml_cuda_mma::DATA_LAYOUT_J_MAJOR
#else
#  define CGDR_C_DL ggml_cuda_mma::DATA_LAYOUT_I_MAJOR
#endif

// GDN_AB_DL: A/B operand fragment layout. RDNA3 distributes WMMA operands mirrored across the
// two half-waves (DATA_LAYOUT_I_MAJOR_MIRRORED, ne=8 half2 -- the v_wmma_f32_16x16x16_f16
// builtin reads a full halfx16 per lane); NVIDIA/CDNA/RDNA4 use I_MAJOR. mma.cuh's
// get_input_data_layout() encodes exactly this switch; same pattern as mmf.cuh tile_A/tile_B.
#define CGDR_AB_DL ggml_cuda_mma::get_input_data_layout()

// GDN_MFMA_LOAD: plain load_ldmatrix in mma.cuh has TURING and AMD_WMMA branches but
// NO AMD_MFMA branch -- on CDNA it falls through to NO_DEVICE_CODE and traps at runtime
// ("unspecified launch failure"). load_generic is the portable element-wise loader and is
// defined in terms of the same get_i/get_j, so it is correct for MFMA tile layouts.
// load_ldmatrix_trans is left alone: it does have an AMD_MFMA branch.
#if defined(AMD_MFMA_AVAILABLE)
#  define CGDR_LOAD ggml_cuda_mma::load_generic
#else
#  define CGDR_LOAD ggml_cuda_mma::load_ldmatrix
#endif

// Check if tensor-core kernels are supported on this architecture; otherwise, fallback or no-op.
#if GDN_TC_MMA
#  if defined(TURING_MMA_AVAILABLE) || defined(AMD_MFMA_AVAILABLE) || defined(AMD_WMMA_AVAILABLE)
#    define GDN_TC_AVAILABLE 1
#  endif
#elif defined(__CUDA_ARCH__) && __CUDA_ARCH__ >= 800
#  define GDN_TC_AVAILABLE 1
#endif

