// ---------------------------------------------------------------- GDN, chunked (TODO 5)
// The recurrence above, S_t = g_t S_{t-1} + k_t d_t^T with d_t = beta_t (v_t - g_t S_{t-1}^T k_t) and o_t = S_t^T q_t,
// in the chunkwise form of the Gated DeltaNet paper.  Inside a chunk of CL tokens, with G_t the sum of the log gates
// from the chunk's first token to t (so gamma_t = exp G_t is the decay since the chunk start):
//   A[t][i] = beta_t exp(G_t - G_i) k_t.k_i  (i < t)      B[t][i] = exp(G_t - G_i) q_t.k_i  (i <= t)
//   Tm = (I + A)^-1                                        Dw = Tm W, W_i = beta_i exp(G_i) k_i;  Du = Tm U, U_i = beta_i v_i
//   D  = Du - Dw S_0           (the chunk's d_t rows)      O  = exp(G) Q S_0 + B D
//   S_CL = exp(G_CL) S_0 + K'^T D, K'_i = exp(G_CL - G_i) k_i
// Everything is FP32 on the plain ALUs (no matrix cores): the serial kernels' arithmetic reassociated, not rounded
// to 16 bits.  A, B, Tm, Dw and Du depend on the chunk's tokens only, so one block per (chunk, head) computes them
// for every chunk at once (gdn_chunk_prep_kernel); the walk from chunk to chunk carries only S, and its value columns
// are independent, so it runs on HV * S/CBV blocks with the state slice in shared memory (gdn_chunk_scan_kernel).
// The serial dependency is CL tokens per step instead of one; the dense products in between are 4x4 register tiles
// fed by float4 shared loads.
constexpr int CL = 64;         // the chunk length
constexpr int CLP = CL + 4;    // the row stride of the transposed tiles: rows stay 16-byte aligned for float4 loads
// dw: [nchunks][HV][CL][S] (Dw), bm: [nchunks][HV][CL][CL] (B), cgo: [nchunks][HV][CL] (G), du: Du into y's rows
__global__ void __launch_bounds__(256) gdn_chunk_prep_kernel(const float* __restrict__ h, const float* __restrict__ gate,
                                                             const float* __restrict__ beta, float* __restrict__ dw,
                                                             float* __restrict__ bm, float* __restrict__ cgo,
                                                             float* __restrict__ du, int64_t T) {
    __shared__ __align__(16) float lds[2 * 64 * CLP];   // K^T and Q^T half tiles [d][t]; then A and Tm [t][i]
    __shared__ float sg[CL], sb[CL];
    float* sKt = lds;
    float* sQt = lds + 64 * CLP;
    float* sA = lds;
    float* sT = lds + CL * (CL + 1);
    static_assert(2 * CL * (CL + 1) <= 2 * 64 * CLP, "A and Tm fit where the K and Q tiles were");
    const int c = blockIdx.x, head = blockIdx.y, qh = head % HK, tid = threadIdx.x;
    const int64_t t0 = (int64_t) c * CL;
    const int tv = (int) ((T - t0) < CL ? (T - t0) : CL);   // this chunk's tokens (the last chunk may be short)
    // the chunk's log gates and betas; G is the running sum from the chunk start (a padded token: 0, it decays nothing)
    if (tid < CL) {
        sg[tid] = tid < tv ? gate[(t0 + tid) * HV + head] : 0.0f;
        sb[tid] = tid < tv ? beta[(t0 + tid) * HV + head] : 0.0f;
    }
    __syncthreads();
    if (tid == 0) {
        float a = 0.0f;
        for (int t = 0; t < CL; ++t) { a += sg[t]; sg[t] = a; }
    }
    __syncthreads();
    if (tid < CL) cgo[((size_t) c * HV + head) * CL + tid] = sg[tid];
    // k_t.k_i and q_t.k_i over the 128 dims in two halves of 64, each staged transposed; a thread's tile is 4 t x 4 i
    const int tt = tid >> 4, ti = tid & 15;
    float aA[4][4], aB[4][4];
#pragma unroll
    for (int x = 0; x < 4; ++x)
#pragma unroll
        for (int yy = 0; yy < 4; ++yy) { aA[x][yy] = 0.0f; aB[x][yy] = 0.0f; }
    for (int dh = 0; dh < 2; ++dh) {
        __syncthreads();
        for (int e = tid; e < CL * 64; e += 256) {
            const int t = e >> 6, d = e & 63;   // d runs across the threads: the reads of h coalesce
            const float* ht = h + (t0 + t) * C;
            const bool ok = t < tv;
            sKt[d * CLP + t] = ok ? ht[HK * S + qh * S + dh * 64 + d] : 0.0f;
            sQt[d * CLP + t] = ok ? ht[qh * S + dh * 64 + d] : 0.0f;
        }
        __syncthreads();
        if (tt >= ti) {   // the tiles above the diagonal stay zero
            for (int d = 0; d < 64; ++d) {
                const float4 kt = *(const float4*) (sKt + d * CLP + tt * 4);
                const float4 ki = *(const float4*) (sKt + d * CLP + ti * 4);
                const float4 qt = *(const float4*) (sQt + d * CLP + tt * 4);
                const float kx[4] = {kt.x, kt.y, kt.z, kt.w}, ky[4] = {ki.x, ki.y, ki.z, ki.w},
                            qx[4] = {qt.x, qt.y, qt.z, qt.w};
#pragma unroll
                for (int x = 0; x < 4; ++x)
#pragma unroll
                    for (int yy = 0; yy < 4; ++yy) {
                        aA[x][yy] = fmaf(kx[x], ky[yy], aA[x][yy]);
                        aB[x][yy] = fmaf(qx[x], ky[yy], aB[x][yy]);
                    }
            }
        }
    }
    __syncthreads();   // the tiles are dead: A and Tm take their place
    float* bg = bm + ((size_t) c * HV + head) * CL * CL;
#pragma unroll
    for (int x = 0; x < 4; ++x)
#pragma unroll
        for (int yy = 0; yy < 4; ++yy) {
            const int t = tt * 4 + x, i = ti * 4 + yy;
            const float r = __expf(sg[t] - sg[i]);
            sA[t * (CL + 1) + i] = (i < t) ? sb[t] * r * aA[x][yy] : 0.0f;
            bg[t * CL + i] = (i <= t) ? r * aB[x][yy] : 0.0f;
        }
    __syncthreads();
    // Tm = (I + A)^-1 by forward substitution: a column per 4 lanes, the rows in order
    {
        const int j = tid >> 2, q = tid & 3;
        for (int t = 0; t < CL; ++t) {
            float s = 0.0f;
            if (t > j)
                for (int i = j + q; i < t; i += 4) s = fmaf(sA[t * (CL + 1) + i], sT[i * (CL + 1) + j], s);
            s += __shfl_xor_sync(0xffffffffu, s, 1);
            s += __shfl_xor_sync(0xffffffffu, s, 2);
            if (q == 0) sT[t * (CL + 1) + j] = (t == j ? 1.0f : 0.0f) - s;
            __syncthreads();
        }
    }
    // Dw = Tm W and Du = Tm U: a thread per (column, half of the tokens); Tm[t][i] = 0 for i > t
    {
        const int k = tid & 127, tg = tid >> 7, iend = tg == 0 ? 32 : CL;
        const float* trow = sT + (tg * 32) * (CL + 1);
        float acc[32];
#pragma unroll
        for (int u = 0; u < 32; ++u) acc[u] = 0.0f;
        for (int i = 0; i < iend; ++i) {
            const float w = (i < tv) ? sb[i] * __expf(sg[i]) * h[(t0 + i) * C + HK * S + qh * S + k] : 0.0f;
#pragma unroll
            for (int u = 0; u < 32; ++u) acc[u] = fmaf(trow[u * (CL + 1) + i], w, acc[u]);
        }
        float* dwo = dw + (((size_t) c * HV + head) * CL + tg * 32) * S + k;
#pragma unroll
        for (int u = 0; u < 32; ++u) { dwo[(size_t) u * S] = acc[u]; acc[u] = 0.0f; }
        for (int i = 0; i < iend; ++i) {
            const float u_i = (i < tv) ? sb[i] * h[(t0 + i) * C + 2 * HK * S + head * S + k] : 0.0f;
#pragma unroll
            for (int u = 0; u < 32; ++u) acc[u] = fmaf(trow[u * (CL + 1) + i], u_i, acc[u]);
        }
#pragma unroll
        for (int u = 0; u < 32; ++u) {
            const int t = tg * 32 + u;
            if (t < tv) du[(t0 + t) * (HV * S) + head * S + k] = acc[u];
        }
    }
}
// The walk over the chunks: a block per (head, CBV value columns), the state slice [S][CBV] in shared memory.  Per
// chunk: P = Dw S and O1 = exp(G) Q S over 32-row slices of k, D = Du - P, O = O1 + B D (two halves of i), then
// S = exp(G_CL) S + K'^T D over two halves of k.  Every product is a 4x4 register tile per thread.
template <int CBV>
__global__ void __launch_bounds__(CL * CBV / 16) gdn_chunk_scan_kernel(float* __restrict__ state, const float* __restrict__ h,
                                                                        const float* __restrict__ dw,
                                                                        const float* __restrict__ bm,
                                                                        const float* __restrict__ cg,
                                                                        float* __restrict__ y, int64_t T) {
    constexpr int NT = CL * CBV / 16, NCT = CBV / 4;   // threads; 4-column tiles across the slice
    static_assert(NT == 16 * NCT, "16 token tiles of 4 by NCT column tiles");
    __shared__ __align__(16) float sS[S * CBV];    // the state slice [k][c]
    __shared__ __align__(16) float sX[64 * CLP];   // Dw and Q' as [kk][t] (32 rows each) | B halves [i][t] | K' [t][kk]
    __shared__ __align__(16) float sD[CL * CBV];   // Du, then D [t][c]
    __shared__ float sg[CL];
    const int head = blockIdx.x / (S / CBV), cb = blockIdx.x % (S / CBV), qh = head % HK, tid = threadIdx.x;
    const int tc = tid % NCT, tt = tid / NCT, c0 = cb * CBV;
    for (int e = tid; e < S * CBV; e += NT) sS[e] = state[((size_t) (e / CBV) * HV + head) * S + c0 + e % CBV];
    const int nch = (int) ((T + CL - 1) / CL);
    for (int c = 0; c < nch; ++c) {
        const int64_t t0 = (int64_t) c * CL;
        const int tv = (int) ((T - t0) < CL ? (T - t0) : CL);
        const float* dwc = dw + ((size_t) c * HV + head) * CL * S;
        const float* bc = bm + ((size_t) c * HV + head) * CL * CL;
        __syncthreads();   // the previous chunk is done with sS, sD and sg
        if (tid < CL) sg[tid] = cg[((size_t) c * HV + head) * CL + tid];
        for (int e = tid; e < CL * CBV; e += NT) {
            const int t = e / CBV;
            sD[e] = t < tv ? y[(t0 + t) * (HV * S) + head * S + c0 + e % CBV] : 0.0f;
        }
        float aP[4][4], aO[4][4];
#pragma unroll
        for (int x = 0; x < 4; ++x)
#pragma unroll
            for (int yy = 0; yy < 4; ++yy) { aP[x][yy] = 0.0f; aO[x][yy] = 0.0f; }
        for (int ks = 0; ks < 4; ++ks) {
            __syncthreads();
            for (int e = tid; e < CL * 32; e += NT) {
                const int t = e >> 5, kk = e & 31;
                sX[kk * CLP + t] = dwc[t * S + ks * 32 + kk];
                sX[(32 + kk) * CLP + t] = t < tv ? __expf(sg[t]) * h[(t0 + t) * C + qh * S + ks * 32 + kk] : 0.0f;
            }
            __syncthreads();
            for (int kk = 0; kk < 32; ++kk) {
                const float4 s4 = *(const float4*) (sS + (ks * 32 + kk) * CBV + tc * 4);
                const float4 w4 = *(const float4*) (sX + kk * CLP + tt * 4);
                const float4 q4 = *(const float4*) (sX + (32 + kk) * CLP + tt * 4);
                const float sv[4] = {s4.x, s4.y, s4.z, s4.w}, wv[4] = {w4.x, w4.y, w4.z, w4.w},
                            qv[4] = {q4.x, q4.y, q4.z, q4.w};
#pragma unroll
                for (int x = 0; x < 4; ++x)
#pragma unroll
                    for (int yy = 0; yy < 4; ++yy) {
                        aP[x][yy] = fmaf(wv[x], sv[yy], aP[x][yy]);
                        aO[x][yy] = fmaf(qv[x], sv[yy], aO[x][yy]);
                    }
            }
        }
        __syncthreads();
#pragma unroll
        for (int x = 0; x < 4; ++x)
#pragma unroll
            for (int yy = 0; yy < 4; ++yy) sD[(tt * 4 + x) * CBV + tc * 4 + yy] -= aP[x][yy];
        __syncthreads();
        for (int ih = 0; ih < 2; ++ih) {
            for (int e = tid; e < CL * 32; e += NT) {
                const int t = e >> 5, ii = e & 31;
                sX[ii * CLP + t] = bc[t * CL + ih * 32 + ii];
            }
            __syncthreads();
            for (int ii = 0; ii < 32; ++ii) {
                const float4 b4 = *(const float4*) (sX + ii * CLP + tt * 4);
                const float4 d4 = *(const float4*) (sD + (ih * 32 + ii) * CBV + tc * 4);
                const float bv[4] = {b4.x, b4.y, b4.z, b4.w}, dv[4] = {d4.x, d4.y, d4.z, d4.w};
#pragma unroll
                for (int x = 0; x < 4; ++x)
#pragma unroll
                    for (int yy = 0; yy < 4; ++yy) aO[x][yy] = fmaf(bv[x], dv[yy], aO[x][yy]);
            }
            __syncthreads();
        }
        const float sc = rsqrtf((float) S);
#pragma unroll
        for (int x = 0; x < 4; ++x) {
            const int t = tt * 4 + x;
            if (t < tv)
                *(float4*) (y + (t0 + t) * (HV * S) + head * S + c0 + tc * 4) =
                    make_float4(aO[x][0] * sc, aO[x][1] * sc, aO[x][2] * sc, aO[x][3] * sc);
        }
        const float gL = __expf(sg[CL - 1]);
        for (int kh = 0; kh < 2; ++kh) {
            for (int e = tid; e < CL * 64; e += NT) {
                const int t = e >> 6, kk = e & 63;
                sX[t * CLP + kk] = t < tv ? __expf(sg[CL - 1] - sg[t]) * h[(t0 + t) * C + HK * S + qh * S + kh * 64 + kk] : 0.0f;
            }
            __syncthreads();
            const int tk = tid / NCT;   // the thread's 4 k rows of this half
            float aS[4][4];
#pragma unroll
            for (int x = 0; x < 4; ++x)
#pragma unroll
                for (int yy = 0; yy < 4; ++yy) aS[x][yy] = 0.0f;
            for (int t = 0; t < CL; ++t) {
                const float4 k4 = *(const float4*) (sX + t * CLP + tk * 4);
                const float4 d4 = *(const float4*) (sD + t * CBV + tc * 4);
                const float kv[4] = {k4.x, k4.y, k4.z, k4.w}, dv[4] = {d4.x, d4.y, d4.z, d4.w};
#pragma unroll
                for (int x = 0; x < 4; ++x)
#pragma unroll
                    for (int yy = 0; yy < 4; ++yy) aS[x][yy] = fmaf(kv[x], dv[yy], aS[x][yy]);
            }
#pragma unroll
            for (int x = 0; x < 4; ++x)
#pragma unroll
                for (int yy = 0; yy < 4; ++yy) {
                    const int idx = (kh * 64 + tk * 4 + x) * CBV + tc * 4 + yy;
                    sS[idx] = fmaf(gL, sS[idx], aS[x][yy]);
                }
            __syncthreads();
        }
    }
    for (int e = tid; e < S * CBV; e += NT) state[((size_t) (e / CBV) * HV + head) * S + c0 + e % CBV] = sS[e];
}

