    for (int head = 0; head < HV; ++head) {
        const int qh = head % HK;
        for (int64_t t = 0; t < T; ++t) {
            const float* ht = in.h.data() + t * C;
            const float* q = ht + qh * S;
            const float* k = ht + HK * S + qh * S;
            const float* v = ht + 2 * HK * S + head * S;
