import pathlib
p = pathlib.Path("src/prefill/kernels.cu"); s = p.read_text(encoding="utf-8")
def rep(old, new, n=1):
    global s
    assert s.count(old) == n, (s.count(old), old[:100])
    s = s.replace(old, new)

# ---- prep: K/Q staging in register batches
rep("""#pragma unroll 1
        for (int j = 0; j < CL * 64 / 256; ++j) {
            const int e = tid + j * 256, t = e >> 6, d = e & 63;   // d runs across the threads: the reads of h coalesce
            const float* ht = h + (t0 + t) * C;
            const bool ok = t < tv;
            sKt[d * CLP + t] = ok ? ht[HK * S + qh * S + dh * 64 + d] : 0.0f;
            sQt[d * CLP + t] = ok ? ht[qh * S + dh * 64 + d] : 0.0f;
        }""",
"""        {
            constexpr int J = CL * 64 / 256;
            float rk[J], rq[J];
#pragma unroll
            for (int j = 0; j < J; ++j) {   // every load issued before the first store; a padded row reads a valid one
                const int e = tid + j * 256, t = e >> 6, d = e & 63, tc = t < tv ? t : tv - 1;
                const float* ht = h + (t0 + tc) * C;   // d runs across the threads: the reads of h coalesce
                rk[j] = ht[HK * S + qh * S + dh * 64 + d];
                rq[j] = ht[qh * S + dh * 64 + d];
            }
#pragma unroll
            for (int j = 0; j < J; ++j) {
                const int e = tid + j * 256, t = e >> 6, d = e & 63;
                sKt[d * CLP + t] = t < tv ? rk[j] : 0.0f;
                sQt[d * CLP + t] = t < tv ? rq[j] : 0.0f;
            }
        }""")
# ---- prep: Du and Dw batches without a conditional around the load (sb is 0 on padded rows)
rep("""#pragma unroll 1
            for (int j = 0; j < 16; ++j) {
                const int i = ib + j;
                uv[j] = (i < tv) ? sb[i] * h[(t0 + i) * C + 2 * HK * S + head * S + k] : 0.0f;
            }""",
"""#pragma unroll
            for (int j = 0; j < 16; ++j) {
                const int i = ib + j, ic = i < tv ? i : tv - 1;
                uv[j] = sb[i] * h[(t0 + ic) * C + 2 * HK * S + head * S + k];   // sb[i] = 0 past the chunk's tokens
            }""")
rep("""#pragma unroll 1
            for (int j = 0; j < 16; ++j) {
                const int i = ib + j;
                wv[j] = (i < tv) ? sb[i] * __expf(sg[i]) * h[(t0 + i) * C + HK * S + qh * S + k] : 0.0f;
            }""",
"""#pragma unroll
            for (int j = 0; j < 16; ++j) {
                const int i = ib + j, ic = i < tv ? i : tv - 1;
                wv[j] = sb[i] * __expf(sg[i]) * h[(t0 + ic) * C + HK * S + qh * S + k];
            }""")
# ---- scan: sD staging
rep("""#pragma unroll 1
        for (int j = 0; j < JD; ++j) {
            const int e = tid + j * NT, t = e / CBV;
            sD[e] = (t < tv && !noload) ? y[(t0 + t) * (HV * S) + head * S + c0 + e % CBV] : 0.0f;
        }""",
"""        {
            float rd[JD];
#pragma unroll
            for (int j = 0; j < JD; ++j) {
                const int e = tid + j * NT, t = e / CBV, tcl = t < tv ? t : tv - 1;
                rd[j] = y[(t0 + tcl) * (HV * S) + head * S + c0 + e % CBV];
            }
#pragma unroll
            for (int j = 0; j < JD; ++j) {
                const int e = tid + j * NT, t = e / CBV;
                sD[e] = (t < tv && !noload) ? rd[j] : 0.0f;
            }
        }""")
# ---- scan: Dw/Q staging
rep("""#pragma unroll 1
            for (int j = 0; j < J32; ++j) {
                const int e = tid + j * NT, t = e >> 5, kk = e & 31;
                const float* ht = h + (t0 + t) * C;
                sX[kk * CLP + t] = (t < tv && !noload) ? dwc[t * C + ks * 32 + kk] : 0.0f;
                sX[(32 + kk) * CLP + t] = (t < tv && !noload) ? __expf(sg[t]) * ht[qh * S + ks * 32 + kk] : 0.0f;
            }""",
"""            {
                float rw[J32], rq[J32];
#pragma unroll
                for (int j = 0; j < J32; ++j) {
                    const int e = tid + j * NT, t = e >> 5, kk = e & 31, tcl = t < tv ? t : tv - 1;
                    rw[j] = dwc[tcl * C + ks * 32 + kk];
                    rq[j] = h[(t0 + tcl) * C + qh * S + ks * 32 + kk];
                }
#pragma unroll
                for (int j = 0; j < J32; ++j) {
                    const int e = tid + j * NT, t = e >> 5, kk = e & 31;
                    const bool ok = t < tv && !noload;
                    sX[kk * CLP + t] = ok ? rw[j] : 0.0f;
                    sX[(32 + kk) * CLP + t] = ok ? __expf(sg[t]) * rq[j] : 0.0f;
                }
            }""")
# ---- scan: B staging
rep("""#pragma unroll 1
            for (int j = 0; j < J32; ++j) {
                const int e = tid + j * NT, t = e >> 5, ii = e & 31;
                sX[ii * CLP + t] = noload ? 0.0f : bc[t * CL + ih * 32 + ii];
            }""",
"""            {
                float rb[J32];
#pragma unroll
                for (int j = 0; j < J32; ++j) {
                    const int e = tid + j * NT, t = e >> 5, ii = e & 31;
                    rb[j] = bc[t * CL + ih * 32 + ii];
                }
#pragma unroll
                for (int j = 0; j < J32; ++j) {
                    const int e = tid + j * NT, t = e >> 5, ii = e & 31;
                    sX[ii * CLP + t] = noload ? 0.0f : rb[j];
                }
            }""")
# ---- scan: K' staging
rep("""#pragma unroll 1
            for (int j = 0; j < J64; ++j) {
                const int e = tid + j * NT, t = e >> 6, kk = e & 63;
                sX[t * CLP + kk] = (t < tv && !noload) ? __expf(sg[CL - 1] - sg[t]) * h[(t0 + t) * C + HK * S + qh * S + kh * 64 + kk] : 0.0f;
            }""",
"""            {
                float rk[J64];
#pragma unroll
                for (int j = 0; j < J64; ++j) {
                    const int e = tid + j * NT, t = e >> 6, kk = e & 63, tcl = t < tv ? t : tv - 1;
                    rk[j] = h[(t0 + tcl) * C + HK * S + qh * S + kh * 64 + kk];
                }
#pragma unroll
                for (int j = 0; j < J64; ++j) {
                    const int e = tid + j * NT, t = e >> 6, kk = e & 63;
                    sX[t * CLP + kk] = (t < tv && !noload) ? __expf(sg[CL - 1] - sg[t]) * rk[j] : 0.0f;
                }
            }""")
p.write_text(s, encoding="utf-8"); print("ok")
