            for (int i = tid; i < CS * CS; i += NT) s_qk[i] = to_fp16(qk_c[i]);
            __syncthreads();
            if (warp < N_TILES) gemm_qkv<BV>(s_qk, s_vnew, s_hd, warp * 16);   // the intra-chunk output
