raw_arguments.command:
cd "E:/work/AI/Strata" && /c/conda_envs/strata/python.exe - <<'EOF'
import pathlib
p = pathlib.Path("src/prefill/kernels.cu"); s = p.read_text(encoding="utf-8")
anchor = "\n// ---------------------------------------------------------------- MoE"
assert s.count(anchor) == 1
s = s.replace(anchor, """
// gdn_out_norm_kernel with a wave per head and 8 heads per block (TODO 5): the kernel above is one 128-thread block
// per (token, head), 199,920 blocks for a 4,165-token chunk, and the 8060S spent 11 ms per layer launching them - as
// long as the recurrence itself.  Lane l holds columns l, l + 32, l + 64, l + 96, so each of the four warp sums covers
// the same 32 columns as the old kernel's warp of that index, reduced by the same butterfly, and the four are added
// in the same order: the same bits.  STRATA_GDN_NORM_OLD=1: the old kernel (A/B).
constexpr int NORM_HEADS = 8;
__global__ void __launch_bounds__(32 * NORM_HEADS) gdn_out_norm_heads_kernel(const float* __restrict__ z,
                                                                             const float* __restrict__ gamma, float eps,
                                                                             float* __restrict__ y,
                                                                             uint16_t* __restrict__ y16) {
    const int64_t t = blockIdx.y;
    const int head = blockIdx.x * NORM_HEADS + threadIdx.y, lane = threadIdx.x;
    const size_t base = (size_t) t * HV * S + (size_t) head * S + lane;
    float oc[4], p[4];
#pragma unroll
    for (int j = 0; j < 4; ++j) oc[j] = y[base + 32 * j];
#pragma unroll
    for (int j = 0; j < 4; ++j) p[j] = warp_sum(oc[j] * oc[j]);
    const float ss = p[0] + p[1] + p[2] + p[3];
    const float r = rsqrtf(ss / (float) S + eps);
#pragma unroll
    for (int j = 0; j < 4; ++j) {
        const float v = oc[j] * r * gamma[lane + 32 * j] * sigm(z[base + 32 * j]);
        y[base + 32 * j] = v;
        y16[base + 32 * j] = hf(v);
    }
}
void gdn_out_norm(const float* z, const float* gamma, float eps, float* y, uint16_t* y16, int64_t T, cudaStream_t cs) {
    static const bool old = std::getenv("STRATA_GDN_NORM_OLD") != nullptr;
    if (T <= 0) return;
    if (old) gdn_out_norm_kernel<<<dim3((unsigned) T, HV), S, 0, cs>>>(z, gamma, eps, y, y16);
    else gdn_out_norm_heads_kernel<<<dim3(HV / NORM_HEADS, (unsigned) T), dim3(32, NORM_HEADS), 0, cs>>>(z, gamma, eps, y, y16);
}
""" + anchor)
n = s.count("gdn_out_norm_kernel<<<dim3((unsigned) T, HV), S, 0, (cudaStream_t) stream>>>(z, gamma, eps, y, y16);")
s = s.replace("gdn_out_norm_kernel<<<dim3((unsigned) T, HV), S, 0, (cudaStream_t) stream>>>(z, gamma, eps, y, y16);",
              "gdn_out_norm(z, gamma, eps, y, y16, T, (cudaStream_t) stream);")
p.write_text(s, encoding="utf-8"); print("call sites", n)
EOF
grep -n "gdn_out_norm" src/prefill/kernels.cu | head; cmake --build build-hip-win --target hip_prefill_gdn_chunk_parity 2>&1 | grep -E " error|Linking HIP exe"

